def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    shirt_patches = image_patch.find("shirt")

    if not man_patches or not shirt_patches:
        return image_patch

    man_shirt_pairs = []
    for man in man_patches:
        for shirt in shirt_patches:
            if abs(man.horizontal_center - shirt.horizontal_center) < 20 and abs(man.vertical_center - shirt.vertical_center) < 20:
                man_shirt_pairs.append((man, shirt))

    if not man_shirt_pairs:
        return image_patch

    man_shirt_pairs.sort(key=lambda pair: (pair[0].horizontal_center, pair[0].vertical_center))
    return man_shirt_pairs[0][0]

modern_c2_ds.program:
def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    man_patches = image_patch.find("man")
    striped_shirt_patches = image_patch.find("striped shirt")

    if not man_patches or not striped_shirt_patches:
        return image_patch

    # Sort patches by their vertical center
    man_patches.sort(key=lambda p: p.vertical_center)
    striped_shirt_patches.sort(key=lambda p: p.vertical_center)

    # Find the man with the striped shirt
    for man in man_patches:
        for shirt in striped_shirt_patches:
            if man.overlaps_with(shirt.left, shirt.lower, shirt.right, shirt.upper):
                return man

    # If no match is found, return the first man patch
    return man_patches[0]

