    woman_patches = image_patch.find("woman")
    floral_patches = image_patch.find("floral design shirt")

    if not woman_patches or not floral_patches:
        return image_patch

    for woman in woman_patches:
        for floral in floral_patches:
            if woman.overlaps_with(floral.left, floral.lower, floral.right, floral.upper):
                return woman

    return woman_patches[0] if woman_patches else floral_patches[0]

