    image_patch = ImagePatch(image)
    women = image_patch.find("woman")
    wine_glasses = image_patch.find("wine glass")

    if not women or not wine_glasses:
        return image_patch

    woman_wine_glass_pairs = []
    for woman in women:
        for wine_glass in wine_glasses:
            if woman.overlaps_with(wine_glass.left, wine_glass.lower, wine_glass.right, wine_glass.upper):
